public int beautifulPairs(List<Integer> A, List<Integer> B) {
    int n = A.size();
    int best = 0;
    for (int j = 0; j < n; j++) {
        for (int v = 1; v <= 1000; v++) {
            if (v == B.get(j)) continue;   // the change is MANDATORY: must differ
            List<Integer> modified = new ArrayList<>(B);
            modified.set(j, v);
            best = Math.max(best, countMatches(A, modified));
        }
    }
    return best;
}

private int countMatches(List<Integer> A, List<Integer> B) {
    Map<Integer, Integer> count = new HashMap<>();
    for (int b : B) count.merge(b, 1, Integer::sum);
    int matches = 0;
    for (int a : A) {
        Integer c = count.get(a);
        if (c != null && c > 0) {
            matches++;
            count.put(a, c - 1);
        }
    }
    return matches;
}

