from collections import Counter

def beautifulPairs(A: list[int], B: list[int]) -> int:
    n = len(A)
    best = 0
    for j in range(n):
        for v in range(1, 1001):
            if v == B[j]:        # the change is MANDATORY: must differ
                continue
            modified = B[:]
            modified[j] = v
            best = max(best, count_matches(A, modified))
    return best

def count_matches(A: list[int], B: list[int]) -> int:
    count = Counter(B)
    matches = 0
    for a in A:
        if count[a] > 0:
            matches += 1
            count[a] -= 1
    return matches

