def beautifulPairs(A: list[int], B: list[int]) -> int:
    count = Counter(A)
    matches = 0
    for b in B:
        if count[b] > 0:
            matches += 1
            count[b] -= 1
    return matches - 1 if matches == len(A) else matches + 1

